
cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    onLoad() {
        this._super();

        let safe_node = cc.find('safe_node', this.node)
        let cfg = cc.vv.gameData.getGameCfg()

        cc.vv.gameData.SetSlotsNode(cc.vv.gameData.GetSlotsScript().node)

        //node pop ui
        let node_pop = cc.find('node_pop_ui', safe_node)
        let script_pop = node_pop.addComponent("Prometheus_Pop")
        script_pop.Init()
        cc.vv.gameData.SetPopNodeScript(script_pop)
        
        //node bonusGame ui
        let node_bonus = cc.find('bonusGame', safe_node)
        let script_bonus = node_bonus.addComponent("Prometheus_BonusGame")
        script_bonus.Init()
        cc.vv.gameData.SetBonusScript(script_bonus)
    },

});
