/**
 * 蒙面英雄的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _slotsNode: null,//slots游戏节点
        isBigStoreToFreeGame: false,//是开启单页玫瑰商店进的免费游戏
        isSmallStoreToFreeGame: false,//是开启玫瑰商店进的免费游戏

    },

    //set nodepopui的脚本
    SetPopNodeScript(scp) {
        this._popupScp = scp
    },

    //get nodepopui的脚本
    GetPopNodeScript(scp) {
        return this._popupScp
    },

    //set slotsNode
    SetSlotsNode(scp) {
        this._slotsNode = scp
    },

    //get slotsNode
    GetSlotsNode() {
        return this._slotsNode
    },

    // 设置游戏的Wheel脚本
    SetBonusScript(scp) {
        this._bonusScp = scp
    },

    // 获得游戏的Wheel脚本
    GetBonusScript() {
        return this._bonusScp
    },

    //解锁五种bonus游戏的押注index
    SetJackpotUnlock(JackpotUnlock) {
        this.JackpotUnlock = JackpotUnlock
    },

    GetJackpotUnlock() {
        return this.JackpotUnlock
    },

    //收集data
    SetCollectInfos(CollectInfos) {
        this._collectInfos = CollectInfos
    },

    GetCollectInfos() {
        return this._collectInfos
    },

    //收集data
    SetCollectInfo(CollectInfo) {
        this._collectInfo = CollectInfo
        let betIndex = this.GetBetIdx()
        this._collectInfos[betIndex - 1] = CollectInfo
    },

    GetCollectInfo() {
        return this._collectInfo
    },

    //是否处于collect多卷轴状态
    SetCollectState(state){
        this._collectState = state
    },
    GetCollectState(){
       return this._collectState
    },

    //是否处于免费游戏中状态  true 是 false 不是
    SetFreeGameState(state){
        this._freeGameState = state
    },

    GetFreeGameState(){
       return this._freeGameState
    },

    //将押注等级转换成押注额度
    //押注等级是从1开始，和服务端保持一致
    IdxToBet(idx) {
        return this._deskInfo.mults[idx]
    },
});

