/**
 * 弹窗管理
 */
let Prometheus_Tools = require('./Prometheus_Tools')

cc.Class({
    extends: cc.Component,

    properties: {
        //cc
        _node_free_Game: null,//免费游戏
        _node_extra_free: null,//免费又中免费
        _node_free_end: null,//免费游戏结束

        //属性
        _storeExtenLine: 0,//玫瑰商店解锁单页后进免费游戏扩展行列
    },

    Init() {
        this._node_free_Game = cc.find('freeGame', this.node)
        this._node_extra_free = cc.find('extraFreeGame', this.node)
        this._node_free_end = cc.find('freeGameEnd', this.node)

        let gameData = cc.vv.gameData
        let slotsSrc = gameData.GetSlotsScript()
        let slotsNode = cc.vv.gameData.GetSlotsNode()

        let freeGameBtn = cc.find("startBtn", this._node_free_Game)
        // let extraFreeGameBtn = cc.find("startBtn", this._node_extra_free)
        let freeGameEndBtn = cc.find("startBtn", this._node_free_end)

        let func1 = ()=>{
            Global.SlotsSoundMgr.playEffect("botton");

            Prometheus_Tools.nodeAni(this._node_free_Game, 3, () => {
                this.node.active = false
            })
            cc.tween(slotsNode)
                .delay(1)
                .call(() => {
                    //修改免费次数显示
                    let totalFree = cc.vv.gameData.GetTotalFree()
                    cc.vv.gameData.SetFreeTime(totalFree - 1)
                    slotsSrc.ShowGameview(true)

                    cc.find("Canvas/safe_node/guochang").active = true
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setAnimation(0, 'skill', false)
                    Global.SlotsSoundMgr.playEffect("fgTrans");
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setCompleteListener((track) => {
                        cc.find("Canvas/safe_node/guochang").active = false
                    })
                })
                .delay(3)
                .call(() => {
                    slotsSrc.sendNextRound()
                })
                .start()
        }

        Global.btnClickEvent(freeGameBtn, () => {
            freeGameBtn.stopAllActions();
            func1();
        }, this)

        // let func2 = ()=>{
        //     Global.SlotsSoundMgr.playEffect("botton");
        //
        //     Prometheus_Tools.nodeAni(this._node_extra_free, 3, () => {
        //         this.node.active = false
        //         slotsSrc.CanDoNextRound()
        //         slotsSrc.ShowGameview(true)
        //     })
        // }
        //
        // Global.btnClickEvent(extraFreeGameBtn, () => {
        //     extraFreeGameBtn.stopAllActions();
        //     func2();
        // }, this)

        let func3 = ()=>{
            Global.SlotsSoundMgr.playEffect("botton");

            Prometheus_Tools.nodeAni(this._node_free_end, 3, () => {
                this.node.active = false
            })
            cc.tween(slotsNode)
                .delay(1)
                .call(() => {
                    slotsSrc.ShowGameview(false)

                    cc.find("Canvas/safe_node/guochang").active = true
                    Global.SlotsSoundMgr.playEffect("fgTrans");
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setAnimation(0, 'skill', false)
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setCompleteListener((track) => {
                        cc.find("Canvas/safe_node/guochang").active = false
                    })
                })
                .delay(3)
                .call(() => {
                    slotsSrc.CanDoNextRound()
                })
                .start()
        }

        Global.btnClickEvent(freeGameEndBtn, () => {
            freeGameEndBtn.stopAllActions();
            func3();
        }, this)

    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    onRcvSubGameAction(msg) {
        //监听51消息 (主要是获取免费游戏次数 玫瑰商店的51消息监听在Prometheus_Store.js)
        if (msg.code != 200) return;
        let data = msg.data;

        let numArr = { 1: 10, 2: 8, 3: 5, 4: 3 } //免费次数
        let lineArr = { 1: 4, 2: 5, 3: 6, 4: 8 }//增加行数
        //solots 增加行数扩展列
        let index = data.choiceId
        cc.vv.gameData.GetSlotsScript().extendLine(lineArr[index], 0.01)
        Prometheus_Tools.nodeAni(this._node_free_Game, 2);
    },

    //重新初始化所有ui 恢复最初样子
    updateUi() {
        for (const iterator of this.node.children) {
            console.log(iterator);
            if (iterator.name != 'pop_bg') {
                iterator.active = false
            }
        }
    },

    //免费游戏
    goFreeGame(num) {
        let freeGameBtn = cc.find("startBtn", this._node_free_Game)
        let gameData = cc.vv.gameData
        let slotsSrc = gameData.GetSlotsScript()
        let slotsNode = cc.vv.gameData.GetSlotsNode()
        this.updateUi()
        this.node.active = true
        this._node_free_Game.active = true
        cc.find("num2", this._node_free_Game).getComponent(cc.Label).string = num / 8
        cc.find("num1", this._node_free_Game).getComponent(cc.Label).string = num
        Prometheus_Tools.nodeAni(this._node_free_Game, 1)
        Global.SlotsSoundMgr.playEffect("fgbegin");
        cc.vv.gameData.checkAutoPlay(freeGameBtn, ()=>{
            Global.SlotsSoundMgr.playEffect("botton");

            Prometheus_Tools.nodeAni(this._node_free_Game, 3, () => {
                this.node.active = false
            })
            cc.tween(slotsNode)
                .delay(1)
                .call(() => {
                    //修改免费次数显示
                    let totalFree = cc.vv.gameData.GetTotalFree()
                    cc.vv.gameData.SetFreeTime(totalFree - 1)
                    slotsSrc.ShowGameview(true)

                    cc.find("Canvas/safe_node/guochang").active = true
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setAnimation(0, 'skill', false)
                    Global.SlotsSoundMgr.playEffect("fgTrans");
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setCompleteListener((track) => {
                        cc.find("Canvas/safe_node/guochang").active = false
                    })
                })
                .delay(3)
                .call(() => {
                    slotsSrc.sendNextRound()
                })
                .start()
        });
    },

    //免费游戏又中免费游戏
    async goExtraFreeGame(num) {
        let gameData = cc.vv.gameData
        let slotsSrc = gameData.GetSlotsScript()
        let slotsNode = cc.vv.gameData.GetSlotsNode()

        let freeGameBtn = cc.find("startBtn", this._node_free_Game)
        // let extraFreeGameBtn = cc.find("startBtn", this._node_extra_free)
        let freeGameEndBtn = cc.find("startBtn", this._node_free_end)
        this.updateUi()
        this.node.active = true
        this._node_extra_free.active = true
        cc.find("num2", this._node_extra_free).getComponent(cc.Label).string = num / 8
        cc.find("num1", this._node_extra_free).getComponent(cc.Label).string = num
        Prometheus_Tools.nodeAni(this._node_extra_free, 1)
        Global.SlotsSoundMgr.playEffect("fgbegin");

        await cc.vv.gameData.awaitTime(2.5);
        // cc.vv.gameData.checkAutoPlay(extraFreeGameBtn, ()=>{
            Global.SlotsSoundMgr.playEffect("botton");

            Prometheus_Tools.nodeAni(this._node_extra_free, 3, () => {
                this.node.active = false
                slotsSrc.CanDoNextRound()
                slotsSrc.ShowGameview(true)
            })
        // });
    },

    //免费游戏结束
    goFreeGameEnd(totalFreeTimes, freeWinCoin) {
        let slotsSrc = cc.vv.gameData.GetSlotsScript()
        let gameData = cc.vv.gameData
        let slotsNode = cc.vv.gameData.GetSlotsNode()

        let freeGameBtn = cc.find("startBtn", this._node_free_Game)
        let extraFreeGameBtn = cc.find("startBtn", this._node_extra_free)
        let freeGameEndBtn = cc.find("startBtn", this._node_free_end)

        this.updateUi()
        this.node.active = true
        this._node_free_end.active = true
        cc.find("num1", this._node_free_end).getComponent(cc.Label).string = totalFreeTimes
        cc.find("WinFrame/totalWinNum", this._node_free_end).getComponent(cc.Label).string = Global.FormatNumToComma(freeWinCoin)
        Prometheus_Tools.nodeAni(this._node_free_end, 1)
        Global.SlotsSoundMgr.playEffect("fgend");
        slotsSrc.Resume();
        //如果是从免费中退出 继续收集游戏
        cc.vv.gameData.GetSlotsScript().updateCollectPigUi()
        cc.vv.gameData.checkAutoPlay(freeGameEndBtn, ()=>{
            Global.SlotsSoundMgr.playEffect("botton");

            Prometheus_Tools.nodeAni(this._node_free_end, 3, () => {
                this.node.active = false
            })
            cc.tween(slotsNode)
                .delay(1)
                .call(() => {
                    slotsSrc.ShowGameview(false)

                    cc.find("Canvas/safe_node/guochang").active = true
                    Global.SlotsSoundMgr.playEffect("fgTrans");
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setAnimation(0, 'skill', false)
                    cc.find("Canvas/safe_node/guochang/spine").getComponent(sp.Skeleton).setCompleteListener((track) => {
                        cc.find("Canvas/safe_node/guochang").active = false
                    })
                })
                .delay(3)
                .call(() => {
                    slotsSrc.CanDoNextRound()
                })
                .start()
        });
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});
