/**
 * 蒙面英雄卷轴
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
    },


    /**重写：和加速没关联的图标如果播放停止动画，就需要自己播放 */
    playReelStop() {
        this._super()
    },

    //高度变化通知
    //如果自己还有需要根据卷轴变化来处理逻辑
    OnReelHeigtChange: function (nAddHeight) {
        this._super(nAddHeight)
        let gameData = cc.vv.gameData
        let slotsNode = cc.vv.gameData.GetSlotsNode()
        //上边框 左右边框 高度变化 只变化一次
        if (this._reelIdx == 1) {
            let cfg = cc.vv.gameData.getGameCfg()

            let reels_frame = cc.find("Canvas/safe_node/slots/reels_frame")
            let frameUp = cc.find("frameUp", reels_frame)
            let frameLeft = cc.find("frameLeft", reels_frame)
            let frameRight = cc.find("frameRight", reels_frame)

            frameLeft.height += nAddHeight
            frameRight.height += nAddHeight
            for (let index = 1; index < 5; index++) {
                cc.find("Canvas/safe_node/slots/reels_bg/role_line" + index).height += nAddHeight
            }
            frameUp.y += nAddHeight
            let widget = cc.find("Canvas/safe_node/jackpot").getComponent(cc.Widget)
            let logo = cc.find("Canvas/safe_node/logo")
            widget.isAbsoluteBottom = false
            if (cfg.row >= 6) {
                widget.bottom = 0.7
                logo.active = false
            }
            if (cfg.row < 6) {
                widget.bottom = 0.64
                logo.active = true
            }
            widget.updateAlignment()
            for (const iterator of cc.find('reels_frame/frameLeft/xianShu', slotsNode).children) {
                iterator.active = false
            }
            for (const iterator of cc.find('reels_frame/frameRight/xianShu', slotsNode).children) {
                iterator.active = false
            }
            cc.find('reels_frame/frameLeft/xianShu/sp' + cfg.row, slotsNode).active = true
            cc.find('reels_frame/frameRight/xianShu/sp' + cfg.row, slotsNode).active = true
        }
    },

    //开始的旋转，回收卷轴
    StartRecycleSymbol: function (nTime) {
        let cfg = cc.vv.gameData.getGameCfg()
        let localRow = cfg.row + 1

        if (this._symbols.length > localRow) {
            let nCount = -(this._symbols.length - (cfg.row + 1))
            this.AddCount(nCount, nTime)
        }
    },

    //重写 显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect: function (bShow, name) {
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find("mask/" + info.antiNode, this.node)
                    if (node && node.active) {
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if (this._stopRightNow) {
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }

                    }
                }
            }
        } else {
            let node = cc.find("mask/" + name, this.node)
            let cfg = cc.vv.gameData.getGameCfg()
            let aniNameArr = { 3: "3", 4: "4", 5: "5", 6: "6", 7: "7", 8: "8" }
            let posArr = { 3: 187.5, 4: 250, 5: 312.5, 6: 375, 7: 437.5, 8: 500 }
            let aniName = 'animation' + aniNameArr[cfg.row]
            if (node) {
                node.getComponent(sp.Skeleton).setAnimation(0, aniName, true)
                node.active = bShow
                node.y = posArr[cfg.row]
            }
            else {
                cc.log("未找到加速节点：mask/node_anti");
            }
        }
    },
});
