    Init() {
        let self = this
        let gameData = cc.vv.gameData

        this._spinePick = cc.find("spinePick", this.node)
        this._bonusGameEnd = cc.find("bonusGameEnd", this.node)
        this._chooseNode = cc.find("chooseNode", this.node)
        this._jpWin = cc.find("jpWin", this._chooseNode)
        this._jpWin.active = false

        let startBtn = cc.find("startBtn", this._spinePick);
        let startFunc = ()=>{
            Global.SlotsSoundMgr.playEffect("botton");

            Prometheus_Tools.nodeAni(this._spinePick, 3, () => {
                let pig3 = cc.find("pig3", this.node)
                pig3.active = true
                pig3.getComponent(sp.Skeleton).setAnimation(0, "Tpig_luoxia_tiao", false)
                pig3.getComponent(sp.Skeleton).addAnimation(0, "JinBiZaZhu", false)
                Global.SlotsSoundMgr.playEffect("5pigUp");

                pig3.getComponent(sp.Skeleton).setCompleteListener((trackEntry, loopCount) => {
                    let name = trackEntry.animation ? trackEntry.animation.name : '';
                    Global.SlotsSoundMgr.playEffect("GpigJump");

                    if (name === 'JinBiZaZhu') {
                        self.updateUi()
                        cc.vv.gameData.GetSlotsScript().showJpNode(false)
                        self._chooseNode.active = true
                        for (let index = 1; index < 6; index++) {
                            let pigNode = cc.find("pig1_" + index, this._chooseNode)
                            pigNode.scale = 0
                            cc.tween(pigNode)
                                .to(0.3, { scale: 1 })
                                .start()
                        }
                        this.numAni()
                        Global.SlotsSoundMgr.playBgm("bgbgm");
                    }
                });

            })
        }

        Global.btnClickEvent(startBtn, () => {
            startBtn.stopAllActions();
            startFunc();
        }, this)

        let endBtn = cc.find("startBtn", this._bonusGameEnd);
        let endFunc = ()=>{
            Global.SlotsSoundMgr.playEffect("collect");

            Prometheus_Tools.nodeAni(this._bonusGameEnd, 3, () => {
                self.node.active = false
                cc.vv.gameData.GetSlotsScript().showJpNode(true)
                cc.vv.gameData.GetSlotsScript().exitBonusGame(this._allBonusGameWin)
            })
        }

        Global.btnClickEvent(endBtn, () => {
            endBtn.stopAllActions();
            endFunc();
        }, this)

        let jpBtn = cc.find("startBtn", this._jpWin);
        let jpFunc = ()=>{
            Global.SlotsSoundMgr.playEffect("collect");

            Prometheus_Tools.nodeAni(this._jpWin, 3, () => {
                self._isShowJpNode = false
                if (self._bonusGame.restCnt === 0) {
                    cc.tween(cc.vv.gameData.GetSlotsNode())
                        .delay(2)
                        .call(() => {
                            self.closeBonusGame()
                        })
                        .start()
                }
            })
        }

        Global.btnClickEvent(jpBtn, () => {
            jpBtn.stopAllActions();
            jpFunc();
        }, this)
    },

    updateUi() {
        for (const iterator of this.node.children) {
            if (iterator.name != 'bg') {
                iterator.active = false;
            }
        }
    },

