let Prometheus_Tools = require('./Prometheus_Tools')

/**
 * 蒙面英雄slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        // cc

        //属性
        _pigNum: 0,//拥有的收集的猪数量
    },

    Init() {
        let cfg = cc.vv.gameData.getGameCfg()
        cfg.row = cfg.realRow
        this._super()
    },

    onLoad() {
        this._super();

        cc.vv.gameData.SetFreeGameState(false)
    },

    //重写
    StartMove: function () {
        this._super()
        //BGM
        if(cc.vv.gameData.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm();
        }

        let collectInfo = cc.vv.gameData.GetCollectInfo()
        let freeGameState =  cc.vv.gameData.GetFreeGameState()

        if (collectInfo && collectInfo.state === 1 && !freeGameState) {
            collectInfo.count -= 1;

            // {state: 0, maxCnt: 7, row: 4, count: 0}
            for (let index = 1; index < 8; index++) {
                let pigNode = cc.find("reels_frame/frameUp/unLockNode/wood/pinkPig" + index, this.node)
                let huoju = cc.find("huoju", pigNode);
                let pinkSpine = cc.find("pinkSpine", pigNode)
                if (index <= collectInfo.count) {
                    if (pigNode.state != 1) {
                        huoju.getComponent(sp.Skeleton).setAnimation(0, "fenTojin", false)
                        huoju.getComponent(sp.Skeleton).addAnimation(0, "jin_idle", true)
                        pigNode.state = 1
                    }

                } else {
                    if (pigNode.state != 0) {
                        huoju.getComponent(sp.Skeleton).setAnimation(0, "jintofen", false)
                        huoju.getComponent(sp.Skeleton).addAnimation(0, "fen_idle", true)
                        pigNode.state = 0

                        pinkSpine.active = true
                        pinkSpine.getComponent(sp.Skeleton).setAnimation(0, "BG_PicksLeft", false)
                        pinkSpine.getComponent(sp.Skeleton).setCompleteListener((trackEntry, loopCount) => {
                            let name = trackEntry.animation ? trackEntry.animation.name : '';
                            pinkSpine.active = false
                        });
                    }

                }
            }
        }
    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine: function (msg) {
        this._gameInfo = msg
        let cards = msg.resultCards
        this.SetSlotsResult(cards)
        this.SetReelStateInfo(cards)
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        this.onSpinEndAction();
    },

    RegisterEvent: function () {
        this._super();
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onEventTotalbetUpdated, this)// 押注额改变
    },

    //下注额改变
    onEventTotalbetUpdated() {
        let GameData = cc.vv.gameData
        let collectInfos = GameData.GetCollectInfos()
        let betIndex = GameData.GetBetIdx()
        GameData.SetCollectInfo(collectInfos[betIndex - 1])
        this.updateCollectPigUi(true)
    },

    async onSpinEndAction() {
        let self = this

        //显示收集猪
        cc.vv.gameData.SetCollectInfo(this._gameInfo.collectInfo)
        await this.moveCoinToPig()
        //显示中奖路线
        this.ShowWinTrace()

        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }

        await new Promise((sucess, failed) => {
            this.ShowBottomWin(nWin, nTotal, true, sucess)
        });

        let rest = cc.vv.gameData.GetFreeTime()
        await this.updateCollectPigUi()
        let freeResult = self._gameInfo.freeResult
        if (this._gameInfo.allFreeCnt > rest && freeResult.freeInfo.freeCnt > 0) {
            //免费游戏中又中免费游戏
            await this.enterDoubleFreeGame()
        } else if (freeResult.freeInfo && freeResult.freeInfo.freeCnt > 0) {
            // 获得免费游戏
            cc.vv.gameData.SetFreeGameState(true)
            await this.CheckEnterFreeGame();
        } else if (this._gameInfo.bonusGame) {
            // 获得bonusGame游戏
            await this.CheckTriggerSubGame(this._gameInfo.bonusGame);
        } else if (this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0) {
            // 结束免费游戏
            cc.vv.gameData.SetFreeGameState(false)
            await this.CheckExitFreeGame();
        } else {
            this.CanDoNextRound()
        }

    },

    //重写 触发bonus轮盘游戏
    async CheckTriggerSubGame(bonusGame) {
        //symbol 动画
        let pigIndex = 0
        if (this._gameInfo && this._gameInfo.resultCards) {
            for (const key in this._gameInfo.resultCards) {
                const element = this._gameInfo.resultCards[key];
                if (element === 301) {
                    pigIndex = Number(key) + 1
                    break;
                }
            }
            if (pigIndex) {
                let symbol = this.GetSymbolByIdx(pigIndex)
                if (symbol) {
                    symbol.playStopAnimation()
                }
            }
        }
        Global.SlotsSoundMgr.playEffect("reelPumpkin");

        await this.awaitTime(1);
        //所有的SYMBOL停止显示动画
        this.stopAllSymbolAni()
        cc.vv.gameData.GetBonusScript().openBonusGame(bonusGame)
    },

    //检查是否触发免费 type 1 中卷轴进免费 2玫瑰商店进免费游戏 
    async CheckEnterFreeGame() {
        Global.SlotsSoundMgr.stopBgm();
        let gameData = cc.vv.gameData
        let popNodeSrc = gameData.GetPopNodeScript()
        let freeResult = this._gameInfo.freeResult
        for (let id of freeResult.freeInfo.scatterIdx) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(true)
            }
        }

        Global.SlotsSoundMgr.playEffect("triggering");
        //保存symbol状态
        this.Backup();
        await this.awaitTime(3)
        // 转场动画播放中 停掉scatter图标动画
        for (let id of freeResult.freeInfo.scatterIdx) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(false)
            }
        }

        //如果是收集中 中免费 恢复行数
        if (gameData.GetCollectState() != 0) {
            //恢复行数
            this.recoverLine(0.3)
            let Bg = cc.find("Canvas/safe_node/spr_bg_collect")
            cc.find('reels_frame/frameUp/unLockNode/wood/goldenMode', this.node).active = false
            cc.find('spine_hero', this.node).active = true
            cc.find('Canvas/safe_node/jackpot').active = true
            await this.awaitTime(0.5)
            gameData.SetCollectState(0)
            Bg.active = false
        }

        //进入免费游戏界面
        popNodeSrc.goFreeGame(freeResult.freeInfo.freeCnt)
    },

    //免费游戏中又进免费
    async enterDoubleFreeGame() {
        let freeResult = this._gameInfo.freeResult
        let popNodeSrc = cc.vv.gameData.GetPopNodeScript()

        for (let id of freeResult.freeInfo.scatterIdx) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(true)
            }
        }
        await this.awaitTime(3);
        for (let id of freeResult.freeInfo.scatterIdx) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(false)
            }
        }
        //进入免费游戏界面
        popNodeSrc.goExtraFreeGame(freeResult.freeInfo.freeCnt)
    },

    //重写
    async ReconnectShow() {
        let GameData = cc.vv.gameData
        let deskInfo = GameData._deskInfo
        let total = GameData.GetTotalFree()
        let rest = GameData.GetFreeTime()

        GameData.SetCollectInfos(deskInfo.collectInfos)
        let betIndex = cc.vv.gameData.GetBetIdx()
        GameData.SetCollectInfo(deskInfo.collectInfos[betIndex - 1])

        if (rest > 0) {
            cc.vv.gameData.SetFreeGameState(true)
        }

        await this.updateCollectPigUi()

        if (rest > 0) {
            //已经处于免费游戏中
            this._bottomScript.ShowFreeModel(true, total - rest, total)
            let nTotal = GameData.GetTotalFreeWin()
            this._bottomScript.SetWin(nTotal)

            this.CanDoNextRound()
            this.ShowGameview(true)
        } else if (deskInfo.bonusGame) {
            // 获得bonusGame游戏
            this._bottomScript.ShowBtnsByState("moveing_1")
            this.CheckTriggerSubGame(deskInfo.bonusGame);
        }

    },

    //重写：退出免费游戏
    async CheckExitFreeGame() {
        Global.SlotsSoundMgr.stopBgm();
        let popNodeSrc = cc.vv.gameData.GetPopNodeScript()
        popNodeSrc.goFreeGameEnd(this._gameInfo.allFreeCnt, this._gameInfo.freeWinCoin)
    },


    async moveCoinToPig() {
        let collectInfo = cc.vv.gameData.GetCollectInfo()
        let pigNode = cc.find("reels_frame/frameUp/unLockNode/wood/pinkPig" + collectInfo.count, this.node)
        let coinNode = cc.find("reels_frame/frameUp/unLockNode/wood/collect_coin", this.node)
        let pigIndex = -1

        for (const key in this._gameInfo.resultCards) {
            const element = this._gameInfo.resultCards[key];
            if (element === 3) {
                pigIndex = Number(key) + 1
                break;
            }
        }

        if (pigIndex === -1) return;
        Global.SlotsSoundMgr.playEffect("reelpig");

        let symbol = this.GetSymbolByIdx(pigIndex)
        let pos = Prometheus_Tools.convetOtherNodeSpace(symbol.node, coinNode.parent)
        symbol.playStopAnimation()

        coinNode.y = pos.y
        coinNode.x = 0
        coinNode.active = true
        cc.tween(coinNode)
            .to(0.5, { x: pigNode.x, y: pigNode.y })
            .call(() => {
                Global.SlotsSoundMgr.playEffect("reelPetBox");
                coinNode.active = false
                //小猪显示正常
                symbol.ShowNormal();
                symbol.ShowKuang(false)
            })
            .start()
        await this.awaitTime(0.5)
    },

    //更新收集猪的ui
    async updateCollectPigUi(isUpdateBet) {
        let gameData = cc.vv.gameData
        let collectInfo = gameData.GetCollectInfo()
        let Bg = cc.find("Canvas/safe_node/spr_bg_collect")

        // {state: 0, maxCnt: 7, row: 4, count: 0}
        for (let index = 1; index < 8; index++) {
            let pigNode = cc.find("reels_frame/frameUp/unLockNode/wood/pinkPig" + index, this.node)
            let huoju = cc.find("huoju", pigNode);
            let pinkSpine = cc.find("pinkSpine", pigNode)
            if (index <= collectInfo.count) {
                if (pigNode.state != 1) {
                    if (isUpdateBet) {
                        huoju.getComponent(sp.Skeleton).setAnimation(0, "jin_idle", false)
                    } else {
                        huoju.getComponent(sp.Skeleton).setAnimation(0, "fenTojin", false)
                        huoju.getComponent(sp.Skeleton).addAnimation(0, "jin_idle", true)
                    }
                    pigNode.state = 1
                }

            } else {
                if (pigNode.state != 0) {
                    if (isUpdateBet) {
                        huoju.getComponent(sp.Skeleton).setAnimation(0, "fen_idle", true)
                    } else {
                        huoju.getComponent(sp.Skeleton).setAnimation(0, "jintofen", false)
                        huoju.getComponent(sp.Skeleton).addAnimation(0, "fen_idle", true)
                    }
                    pigNode.state = 0

                    pinkSpine.active = true
                    pinkSpine.getComponent(sp.Skeleton).setAnimation(0, "BG_PicksLeft", false)
                    pinkSpine.getComponent(sp.Skeleton).setCompleteListener((trackEntry, loopCount) => {
                        let name = trackEntry.animation ? trackEntry.animation.name : '';
                        pinkSpine.active = false
                    });
                }

            }
        }
        if (collectInfo.state === 1) {
            // if (gameData.GetCollectState() != 1 && !gameData.GetFreeGameState()) {
            if (!gameData.GetFreeGameState() && (this._cfg.row != collectInfo.row)) {
                //扩展行数
                let needChange = false
                if(this._bottomScript.GetSpinBtnState()){
                    needChange = true
                    this._bottomScript.ShowBtnsByState("moveing_1")
                }

                this.extendLine(collectInfo.row, 0.5)
                cc.find('spine_hero', this.node).active = false
                cc.find('Canvas/safe_node/jackpot').active = false
                cc.find('reels_frame/frameUp/unLockNode/wood/goldenMode', this.node).active = true
                Bg.active = true
                gameData.SetCollectState(1)
                await this.awaitTime(0.5)
                if(needChange){
                    this.CanDoNextRound()
                }
            }

        } else {
            if (gameData.GetCollectState() != 0) {
                //恢复行数
                let needChange = false
                if(this._bottomScript.GetSpinBtnState()){
                    needChange = true
                    this._bottomScript.ShowBtnsByState("moveing_1")
                }

                this.recoverLine(0.5)
                cc.find('reels_frame/frameUp/unLockNode/wood/goldenMode', this.node).active = false
                cc.find('spine_hero', this.node).active = true
                cc.find('Canvas/safe_node/jackpot').active = true
                Bg.active = false
                gameData.SetCollectState(0)
                await this.awaitTime(0.5)
                if(needChange){
                    this.CanDoNextRound()
                }

            }
        }

    },

    //退出bonus游戏显示bugwin
    async exitBonusGame(_allBonusGameWin) {
        Global.SlotsSoundMgr.playNormalBgm(true);
        let haveWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
        await cc.vv.gameData.GetSlotsScript().ShowBottomWin(_allBonusGameWin, _allBonusGameWin + haveWin, true, null, 1)
        this.CanDoNextRound()
    },

    //扩展列的行数 立即生效(用于免费游戏中)  count行数 time 时间 
    extendLine(count, time = 0.01) {

        let GameCfg = cc.vv.gameData.getGameCfg()
        let addLineNum = count - GameCfg.row
        GameCfg.row = count
        //修改topaniNode的高度
        let topAniNode = cc.find("Canvas/safe_node/slots/top_ani")
        topAniNode.height = count * GameCfg.symbolSize.height
        for (let i = 0; i < 5; i++) {
            this._reels[i].AddCount(addLineNum, time)
        }
        Global.SlotsSoundMgr.playEffect("reelup");

        this._row = this._cfg.row
    },

    //恢复列的行数 （退出免费游戏）
    recoverLine(time = 0.01) {
        let GameCfg = cc.vv.gameData.getGameCfg()

        let data1 = GameCfg.row
        let data2 = GameCfg.realRow
        let addLineNum = data2 - data1
        //修改topaniNode的高度
        let topAniNode = cc.find("Canvas/safe_node/slots/top_ani")
        topAniNode.height = data2 * GameCfg.symbolSize.height
        //恢复卷轴
        if (addLineNum != 0) {
            for (let i = 0; i < 5; i++) {
                this._reels[i].AddCount(addLineNum, time)
            }
        }
        Global.SlotsSoundMgr.playEffect("reeldown");

        //恢复卷轴正常行数
        this._cfg.row = this._cfg.realRow
        this._row = this._cfg.row
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    async ShowGameview(bFree) {
        if (bFree) {
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
            this._bottomScript.ShowFreeModel(true, total - rest, total)

            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            this._bottomScript.SetWin(nTotal)
            Global.SlotsSoundMgr.playBgm("fgbgm");
        }
        else {
            this._bottomScript.ShowFreeModel(false)
            Global.SlotsSoundMgr.playNormalBgm(true)
        }

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if (normalBg) {
            normalBg.active = !bFree
        }
        if (normalFree) {
            normalFree.active = bFree
        }
    },

    //停止所有的symbol动画
    stopAllSymbolAni() {
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            for (let i = 0; i < item._symbols.length; i++) {
                let element = item._symbols[i];
                element.ShowNormal();
                element.ShowKuang(false)
            }
        }
    },

    //显示或者隐藏奖池
    showJpNode(isShow) {
        let jackpot = cc.find("Canvas/safe_node/jackpot")
        let logo = cc.find("Canvas/safe_node/logo")
        if (!isShow) {
            jackpot.active = false
            logo.active = false
        } else {
            jackpot.active = true
            let widget = jackpot.getComponent(cc.Widget)
            widget.isAbsoluteBottom = false
            if (this._cfg.row >= 6) {
                widget.bottom = 0.7
                logo.active = false
            }
            if (this._cfg.row < 6) {
                widget.bottom = 0.64
                logo.active = true
            }
            widget.updateAlignment()
        }

    },

    // 发送下一次旋转请求
    sendNextRound() {
        this._bottomScript.SendSpinReq();
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});
